  "INSERT INTO assessments (id,org_id,title,type,job_id,description,instructions,duration_min,pass_score,version,status,created_by) VALUES (1,1,'Excel intermedio — conciliación y análisis','mcq',1,'Evalúa fórmulas, búsquedas y criterios de conciliación aplicados al cierre mensual.','Responde las 6 preguntas. Puedes usar Excel como apoyo. Se evalúa exactitud del criterio, no la velocidad.',30,70,1,'active',4)",
  "INSERT INTO assessments (id,org_id,title,type,job_id,description,instructions,duration_min,pass_score,version,status,created_by) VALUES (2,1,'Caso práctico — cierre contable con diferencia','written',1,'Caso con una diferencia de 1.240 USD entre mayor y auxiliar.','Explica el procedimiento de detección, las verificaciones y cómo documentarías el ajuste. Se califica con rúbrica.',45,70,1,'active',4)",
  "INSERT INTO assessment_questions (id,org_id,assessment_id,prompt,kind,options,correct_index,points) VALUES (1,1,1,'¿Qué función permite buscar un valor en la primera columna de una tabla y devolver otra columna?','mcq','[\"BUSCARV / BUSCARX\",\"SUMA\",\"CONTAR.SI\",\"IZQUIERDA\"]',0,1)",
  "INSERT INTO assessment_questions (id,org_id,assessment_id,prompt,kind,options,correct_index,points) VALUES (2,1,1,'Al concatenar criterios en SUMAR.SI.CONJUNTO, ¿qué operador se usa para \"mayor o igual que\"?','mcq','[\"\\\">=\\\"\",\"\\\"=\\\"\",\"\\\"<>\\\"\",\"\\\"+\\\"\"]',0,1)",
  "INSERT INTO assessment_questions (id,org_id,assessment_id,prompt,kind,options,correct_index,points) VALUES (3,1,1,'Una tabla dinámica sirve principalmente para…','mcq','[\"Resumir y agrupar grandes volúmenes de datos\",\"Cambiar el formato de una celda\",\"Crear macros\",\"Proteger la hoja\"]',0,1)",
  "INSERT INTO assessment_questions (id,org_id,assessment_id,prompt,kind,options,correct_index,points) VALUES (4,1,1,'En una conciliación bancaria, la diferencia entre saldo en libros y extracto puede originarse por…','mcq','[\"Partidas en tránsito y cheques no cobrados\",\"Un error de formato de fecha\",\"El ancho de la columna\",\"El color de la celda\"]',0,1)",
  "INSERT INTO assessment_questions (id,org_id,assessment_id,prompt,kind,options,correct_index,points) VALUES (5,1,1,'¿Cuál fórmula cuenta celdas que cumplen dos condiciones?','mcq','[\"CONTAR.SI.CONJUNTO\",\"CONTAR\",\"SUMA\",\"PROMEDIO\"]',0,1)",
  "INSERT INTO assessment_questions (id,org_id,assessment_id,prompt,kind,options,correct_index,points) VALUES (6,1,1,'Para limpiar espacios sobrantes en un texto se usa…','mcq','[\"ESPACIOS o RECORTAR\",\"REDONDEAR\",\"TEXTO\",\"ABS\"]',0,1)",
  "INSERT INTO assessment_questions (org_id,assessment_id,prompt,kind,options,correct_index,points,rubric) VALUES (1,2,'Describe cómo detectarías y documentarías la diferencia de 1.240 USD.','open','[]',NULL,10,'Exactitud (40%): identifica partidas en tránsito y errores de registro. Procedimiento (30%): pasos lógicos y verificables. Interpretación (20%): explica el impacto. Presentación (10%): documentación clara.')",
